package local.cleartv.mobile;
import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;

/** Small bounded HTTP/1.1 server for explicitly enabled LAN features. No CORS. */
public final class LanHttp implements AutoCloseable {
 public interface Handler{Response handle(String method,String path,Map<String,String> headers,byte[] body)throws Exception;}
 public static final class Response{public int code;public String type;public byte[] data;public Map<String,String> headers=new LinkedHashMap<>();public Response(int c,String t,byte[] d){code=c;type=t;data=d;}public static Response json(String s)throws Exception{return new Response(200,"application/json; charset=utf-8",s.getBytes("UTF-8"));}}
 private final ServerSocket server;private final ExecutorService workers=new ThreadPoolExecutor(3,3,0L,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<Runnable>(12));private final Set<Socket> connections=Collections.synchronizedSet(new HashSet<Socket>());private volatile boolean closed;
 public LanHttp(int port,Handler handler)throws Exception{server=new ServerSocket();try{server.setReuseAddress(true);server.bind(new InetSocketAddress(port));}catch(Exception e){try{server.close();}catch(Exception ignored){}workers.shutdownNow();throw e;}Thread t=new Thread(()->{while(!closed){try{Socket s=server.accept();synchronized(connections){if(closed){s.close();return;}connections.add(s);try{workers.execute(()->serve(s,handler));}catch(RejectedExecutionException full){connections.remove(s);s.close();}}}catch(Exception e){if(closed)return;}}},"tv-morph-lan");t.setDaemon(true);t.start();}
 private static final class DeadlineInput extends FilterInputStream{final Socket socket;final long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);DeadlineInput(Socket s)throws IOException{super(s.getInputStream());socket=s;}void budget()throws IOException{long ms=TimeUnit.NANOSECONDS.toMillis(until-System.nanoTime());if(ms<=0)throw new SocketTimeoutException();socket.setSoTimeout((int)Math.min(5000,Math.max(1,ms)));}public int read()throws IOException{budget();return in.read();}public int read(byte[] bytes,int offset,int length)throws IOException{budget();return in.read(bytes,offset,length);}}
 private static String line(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();int b;while((b=in.read())!=-1){if(b==10)break;if(b!=13)out.write(b);if(out.size()>8192)throw new IOException("Header too large");}return out.toString("US-ASCII");}
 private void serve(Socket socket,Handler handler){try(Socket s=socket){s.setSoTimeout(5000);InputStream in=new DeadlineInput(s);Response response;boolean head=false;
  try{String[] first=line(in).split(" ");if(first.length!=3)throw new IOException("Invalid request");head=first[0].equals("HEAD");Map<String,String> headers=new HashMap<>();int total=0;String h;while(!(h=line(in)).isEmpty()){total+=h.length();if(total>16384)throw new IOException("Header too large");int colon=h.indexOf(':');if(colon>0)headers.put(h.substring(0,colon).toLowerCase(Locale.US),h.substring(colon+1).trim());}
   int length=Integer.parseInt(headers.getOrDefault("content-length","0"));if(length<0||length>1048576||headers.containsKey("transfer-encoding"))throw new IOException("Invalid body");byte[] body=new byte[length];for(int p=0;p<length;){int n=in.read(body,p,length-p);if(n<0)throw new EOFException();p+=n;}
   if(headers.containsKey("origin"))response=new Response(403,"text/plain",new byte[0]);else response=handler.handle(first[0],first[1],headers,body);
  }catch(Exception e){response=new Response(400,"application/json","{\"error\":\"Request rejected\"}".getBytes("UTF-8"));}
  OutputStream out=s.getOutputStream();StringBuilder extra=new StringBuilder();for(Map.Entry<String,String> e:response.headers.entrySet())extra.append(e.getKey()).append(": ").append(e.getValue()).append("\r\n");out.write(("HTTP/1.1 "+response.code+" Response\r\nContent-Type: "+response.type+"\r\nContent-Length: "+response.data.length+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\n"+extra+"Connection: close\r\n\r\n").getBytes("US-ASCII"));if(!head)out.write(response.data);out.flush();
 }catch(Exception ignored){}finally{connections.remove(socket);}}
 public void close(){synchronized(connections){closed=true;try{server.close();}catch(Exception ignored){}workers.shutdownNow();for(Socket s:connections)try{s.close();}catch(Exception ignored){}connections.clear();}}
}
